WITH base AS (SELECT *, LENGTH(location) AS location_length FROM departments WHERE dept_name IS NOT NULL), metrics AS (SELECT id, dept_name, location, budget, LAG(location_length, 2, 0) OVER (PARTITION BY dept_name ORDER BY budget, id) AS prev_location_length, ROW_NUMBER() OVER w_running AS seq_no, LAG(location_length, 1) OVER w_running AS prev_location_length_2, AVG(location_length) OVER (PARTITION BY location, dept_name ORDER BY budget, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS location_length_avg_3_prior, SUM(location_length) OVER (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_location_length FROM base WINDOW w_running AS (ORDER BY location_length, id)), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY location ORDER BY running_location_length NULLS LAST, id) AS rn FROM metrics QUALIFY rn = 1), eligible AS (SELECT s.* FROM latest s WHERE NOT EXISTS (SELECT 1 FROM employees ch WHERE ch.dept_id = s.id AND ch.dept_id IN (18, 34, 37))), kept_keys AS (SELECT id FROM eligible INTERSECT SELECT id FROM departments WHERE budget <= 1309000), verified AS (SELECT s.* FROM eligible s INNER JOIN kept_keys k ON s.id = k.id), stats AS (SELECT CASE WHEN budget >= 3930000 THEN 'PREMIUM' ELSE 'STANDARD' END AS budget_tier, seq_no, ROUND(SUM(prev_location_length_2) / NULLIF(COUNT(CASE WHEN dept_name = 'Marketing' THEN 1 END), 0), 2) AS prev_location_length_2_per_marketing, COUNT(*) AS row_count, ROUND(SUM(seq_no) / NULLIF(COUNT(CASE WHEN dept_name = 'Engineering' THEN 1 END), 0), 2) AS seq_no_per_engineering, SUM(CASE WHEN location = 'New York' THEN prev_location_length_2 ELSE 0 END) AS new_york_prev_location_length_2, COUNT(CASE WHEN location = 'Bangkok' THEN 1 END) AS bangkok_count, ROUND(AVG(running_location_length), 2) AS avg_running_location_length, PERCENT_RANK() OVER (PARTITION BY CASE WHEN budget >= 3930000 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY COUNT(CASE WHEN location = 'Bangkok' THEN 1 END) DESC) AS bangkok_count_percent_rank FROM verified GROUP BY CASE WHEN budget >= 3930000 THEN 'PREMIUM' ELSE 'STANDARD' END, seq_no) SELECT budget_tier, seq_no, prev_location_length_2_per_marketing, row_count, seq_no_per_engineering, bangkok_count, bangkok_count_percent_rank FROM stats
